        return {"external_id": existing.external_id, "duplicate": True}
    rec = StoredContract(external_id=f"CS-{uuid.uuid4().hex[:10].upper()}", idempotency_key=idempotency_key,
                         sha256=payload.get("sha256", ""), payload=payload)
    session.add(rec)
